function checkAutomaticUpdateIfDue(){if(!settings.autoUpdate||!isAutomaticUpdateCheckDue(settings.lastAutoUpdateCheckAt))return;settings.lastAutoUpdateCheckAt=Date.now();persistSettings();void checkForAppUpdates(true);}
async function checkForAppUpdates(automatic:boolean,reinstall=false){if(!window.desktop)return;try{const update=await window.desktop.checkForUpdates();if(!update.available&&!reinstall){if(!automatic)toast(`Обновлений нет. Установлена версия ${update.currentVersion}; последняя версия ${update.version}.`);return;}const title=reinstall?'Переустановить приложение?':'Доступно обновление';const description=reinstall?`<p>Будет заново загружена и установлена версия <b>${esc(update.version)}</b>, даже если она уже установлена. Это временная кнопка для проверки обновления интерфейса в открытом окне.</p>`:`<p>Установлена версия <b>${esc(update.currentVersion)}</b>, доступна версия <b>${esc(update.version)}</b>. Полный пакет приложения загрузится из GitHub и проверится по контрольной сумме. Интерфейс обновится в этом окне без его закрытия. Черновики, шаблоны и словарь сохранятся. Изменения системной части приложения вступят в силу при следующем обычном запуске.</p>`;const d=dialog(title,`${description}<p>Проверяются только сведения о версии; медицинские тексты и данные пациентов не отправляются.</p><div id="update-progress" class="update-progress hidden"><div class="update-progress-caption"><span id="update-progress-label">Подготовка загрузки…</span><b id="update-progress-percent">0%</b></div><div class="update-progress-track"><div id="update-progress-fill"></div></div><small id="update-progress-detail">Подключение к GitHub</small><details id="update-error-details" hidden><summary>Подробности ошибки</summary><pre id="update-error-text"></pre></details></div>`,'<button class="btn" data-close>Позже</button><button class="btn primary" id="install-update">'+(reinstall?'Скачать и переустановить':'Скачать и установить')+'</button>');d.querySelector('#install-update')!.addEventListener('click',async()=>{const button=d.querySelector<HTMLButtonElement>('#install-update')!;button.disabled=true;button.textContent='Загрузка и установка…';const progress=d.querySelector<HTMLElement>('#update-progress')!;progress.classList.remove('hidden');window.desktop!.onUpdateProgress(value=>{const label=d.querySelector<HTMLElement>('#update-progress-label')!;const percent=d.querySelector<HTMLElement>('#update-progress-percent')!;const detail=d.querySelector<HTMLElement>('#update-progress-detail')!;const fill=d.querySelector<HTMLElement>('#update-progress-fill')!;const mb=(bytes:number)=>(bytes/1048576).toFixed(1)+' МБ';if(value.stage==='error'){label.textContent='Не удалось установить обновление';percent.textContent='';detail.textContent=value.logFile?`Журнал: ${value.logFile}`:(value.message??'Неизвестная ошибка');d.querySelector<HTMLElement>('#update-error-details')!.hidden=false;d.querySelector<HTMLElement>('#update-error-text')!.textContent=(value.message??'Неизвестная ошибка')+(value.logFile?'\n\nЖурнал: '+value.logFile:'');fill.classList.remove('indeterminate');fill.style.width='0';return;}if(value.stage==='downloading'){label.textContent='Загрузка пакета обновления';percent.textContent=value.percent===null?'':value.percent+'%';detail.textContent=value.total?`${mb(value.loaded)} из ${mb(value.total)}`:`Загружено ${mb(value.loaded)}`;fill.style.width=value.percent===null?'30%':value.percent+'%';fill.classList.toggle('indeterminate',value.percent===null);}else{fill.classList.remove('indeterminate');fill.style.width='100%';percent.textContent='100%';label.textContent=value.stage==='verifying'?'Проверка файла':value.stage==='installing'?'Установка обновления':'Установка завершена';detail.textContent=value.stage==='verifying'?'Проверяется контрольная сумма':value.stage==='installing'?'Распаковка и настройка ярлыка':'Готово';}});try{await window.desktop!.installUpdate(reinstall);const installedVersion=await window.desktop!.getApplicationVersion();const versionLabel=document.querySelector('#application-version');if(versionLabel)versionLabel.textContent=installedVersion;toast(`Интерфейс обновлён до версии ${installedVersion} в текущем окне. Изменения системной части вступят в силу при следующем запуске.`);closeDialog();}catch(error){button.disabled=false;button.textContent=reinstall?'Скачать и переустановить':'Скачать и установить';d.querySelector<HTMLElement>('#update-progress-label')!.textContent='Не удалось установить обновление';d.querySelector<HTMLElement>('#update-progress-detail')!.textContent='Подробности доступны в журнале обновлений';d.querySelector<HTMLElement>('#update-error-details')!.hidden=false;d.querySelector<HTMLElement>('#update-error-text')!.textContent=(error as Error).message;toast(`Не удалось установить обновление: ${(error as Error).message}`,true);}finally{window.desktop!.clearUpdateProgress();}});}catch(error){if(!automatic)toast(`Не удалось проверить обновления: ${(error as Error).message}`,true);}}
