function paginateBrowserPreview(html:string):string {const source=document.createElement('div');source.className='report-content';source.innerHTML=html;const blocks:HTMLElement[]=[];const collect=(node:Element)=>{if(node.matches('section[data-report-section]')){[...node.children].forEach(child=>collect(child));return;}blocks.push(node.cloneNode(true) as HTMLElement);};[...source.children].forEach(child=>collect(child));const scratch=document.createElement('article');scratch.className='export-preview-paper preview-measure';const measure=document.createElement('div');measure.className='report-content';scratch.append(measure);document.body.append(scratch);const pages:HTMLElement[]=[];let page=0,used=0;const limit=850;const makePage=()=>{const paper=document.createElement('article');paper.className='export-preview-paper';const content=document.createElement('div');content.className='report-content';paper.append(content);pages.push(paper);page++;used=0;return content;};let target=makePage();for(const block of blocks){measure.innerHTML='';measure.append(block.cloneNode(true));const height=Math.max(1,measure.firstElementChild?.getBoundingClientRect().height??20);const beginsConclusion=/^(?:ЗАКЛЮЧЕНИЕ|Заключение|Рекомендац|Вывод|Совет)/i.test((block.textContent??'').trim());if(used+height>limit&&target.children.length){target=makePage();}else if(beginsConclusion&&page>1&&!target.children.length&&pages.length>1){const previous=pages.at(-2)!.querySelector('.report-content')!;const preceding=previous.lastElementChild;if(preceding){preceding.remove();target.append(preceding);used+=preceding.getBoundingClientRect().height;}}target.append(block);used+=height;}scratch.remove();return pages.map((paper,index)=>`<div class="preview-page"><span class="preview-page-number">Страница ${index+1}</span>${paper.outerHTML}</div>`).join('');}
